// ============================================================================
// CertBenchMain.cpp — benchmark for the verifiable-construction
// protocol: Farkas non-partition certificates + strict-witness
// partition certificates, generated by replaying the honest construction.
//
// Usage:  CertBench <n> <d>
//
// Cloud side:  replay the built AOF-tree, emit one partition certificate per
//   internal node and one non-partition certificate per elimination /
//   leaf-remaining candidate / resolution pair check.  Farkas multipliers are
//   found with HiGHS over the homogeneous constraint columns (lower box
//   facets + ancestor cut normals); with homogeneous pair planes the constant
//   c is always 0 (the origin lies in every region's closure), exercising the
//   c >= 0 relaxation on every certificate.
// Owner side:  verify every certificate arithmetically (identity + signs +
//   strict witness membership), then compute tuples + commitments (the work
//   also paid locally).  Reports counts, bytes, timings, and falsification
//   self-tests.
// ============================================================================

#include <print>
#include <format>
#include <fstream>
#include <filesystem>
#include <random>
#include <Highs.h>
#include "AofAds.h"

using Clock = std::chrono::high_resolution_clock;
static double secs(Clock::time_point a, Clock::time_point b) {
    return std::chrono::duration<double>(b - a).count();
}

namespace cb {

// A homogeneous constraint  a·x >= 0  (lower box facet e_t, or +-cut normal).
struct Constraint { Eigen::VectorXd a; };

struct FarkasCert {
    int p = 0, c = 0;                       // the pair (unordered ids)
    int sign = 0;                           // +1: f_min - f_max >= 0 on region; -1: <= 0
    std::vector<std::pair<int, double>> y;  // sparse multipliers over the constraint list
};
struct PartitionCert {
    int p = 0, j = 0;
    Eigen::VectorXd xNeg, xPos;             // strict-interior witnesses of the two children
    const aof::Node* dbgNode = nullptr;     // debug only
};

struct Stats {
    size_t nPartition = 0, nNonPartition = 0;
    size_t nnzTotal = 0, maxNnz = 0;
    size_t bytes = 0;
    double genSec = 0, verifySec = 0;
    size_t genFailures = 0, verifyFailures = 0;
};

class Replayer {
public:
    const aof::FunctionTable* F;
    const std::vector<Eigen::VectorXd>* planes;
    int n, d;
    Stats st;
    std::vector<FarkasCert> farkas;
    std::vector<PartitionCert> parts;
    Highs highs;

    Replayer(const aof::FunctionTable& f, const std::vector<Eigen::VectorXd>& p)
        : F(&f), planes(&p), n(f.n), d(f.d) {
        highs.setOptionValue("output_flag", false);
    }

    Eigen::VectorXd pairPlane(int a, int b) const {   // A_min - A_max
        int i = std::min(a, b), j = std::max(a, b);
        return (*planes)[Generator::pair_index(size_t(i), size_t(j), size_t(n))];
    }

    // ---- Cloud: find sparse y >= 0 with  sum y_t a_t = w  over columns G.
    bool solveFarkas(const std::vector<Constraint>& G, const Eigen::VectorXd& w,
                     std::vector<std::pair<int, double>>& out) {
        HighsLp lp;
        int k = int(G.size());
        lp.num_col_ = k; lp.num_row_ = d;
        lp.col_cost_.assign(k, 1.0);                       // min sum y (canonical, sparse-ish)
        lp.col_lower_.assign(k, 0.0);
        lp.col_upper_.assign(k, kHighsInf);
        lp.row_lower_.resize(d); lp.row_upper_.resize(d);
        for (int r = 0; r < d; ++r) { lp.row_lower_[r] = w[r]; lp.row_upper_[r] = w[r]; }
        lp.a_matrix_.format_ = MatrixFormat::kColwise;
        lp.a_matrix_.start_.resize(k + 1);
        for (int c = 0; c < k; ++c) {
            lp.a_matrix_.start_[c] = int(lp.a_matrix_.index_.size());
            for (int r = 0; r < d; ++r) {
                double v = G[c].a[r];
                if (v != 0.0) { lp.a_matrix_.index_.push_back(r); lp.a_matrix_.value_.push_back(v); }
            }
        }
        lp.a_matrix_.start_[k] = int(lp.a_matrix_.index_.size());
        highs.passModel(lp);
        if (highs.run() != HighsStatus::kOk) return false;
        if (highs.getModelStatus() != HighsModelStatus::kOptimal) return false;
        const auto& sol = highs.getSolution();
        out.clear();
        for (int c = 0; c < k; ++c)
            if (sol.col_value[c] > 1e-12) out.push_back({ c, sol.col_value[c] });
        return true;
    }

    void emitNonPartition(int p, int c, const std::vector<Constraint>& G,
                          const Eigen::VectorXd& witness) {
        Eigen::VectorXd w = pairPlane(p, c);
        double s = w.dot(witness);
        int sign = (s >= 0.0) ? +1 : -1;
        auto t0 = Clock::now();
        FarkasCert fc; fc.p = p; fc.c = c; fc.sign = sign;
        bool ok = solveFarkas(G, sign > 0 ? w : Eigen::VectorXd(-w), fc.y);
        if (!ok) {
            // Near-degenerate witness may have guessed the wrong side; the
            // honest sign is the one with a feasible dual — retry flipped.
            fc.sign = -sign;
            ok = solveFarkas(G, fc.sign > 0 ? w : Eigen::VectorXd(-w), fc.y);
        }
        auto t1 = Clock::now();
        st.genSec += secs(t0, t1);
        if (!ok) {
            // Both signs infeasible: the pair genuinely crosses the region,
            // i.e., the floating-point geometric kernel deviated from the
            // exact-arithmetic construction here (missed sliver split).  The
            // protocol DETECTS the deviation — reported as a headline stat.
            st.genFailures++;
            return;
        }
        st.nNonPartition++;
        st.nnzTotal += fc.y.size();
        st.maxNnz = std::max(st.maxNnz, fc.y.size());
        st.bytes += 9 + fc.y.size() * 12;              // pair ids + sign + (idx,val) pairs
        farkas.push_back(std::move(fc));
        ctxNP.push_back(int(ctxStack.size()) - 1);     // which context this cert belongs to
    }
    void emitPartition(int p, int j, const aof::Node* v) {
        st.nPartition++;
        PartitionCert pc; pc.p = p; pc.j = j; pc.dbgNode = v;
        pc.xNeg = v->left->interior_witness; pc.xPos = v->right->interior_witness;
        st.bytes += 8 + 2 * size_t(d) * 8;
        parts.push_back(std::move(pc));
        ctxP.push_back(int(ctxStack.size()) - 1);
    }

    // Context bookkeeping so the owner can re-verify with the same G lists.
    std::vector<std::vector<Constraint>> ctxStack;     // flattened contexts
    std::vector<int> ctxNP, ctxP;                      // cert -> context index

    void replayTask(const aof::Node* node, std::vector<int> S, std::vector<Constraint> G) {
        while (true) {
            bool absent = (!node || node->is_placeholder());
            int pv = absent ? INT32_MAX : node->target_function_id;
            // Resolution draws: every scope function below the subtree pivot.
            ctxStack.push_back(G);
            while (S.size() >= 2 && S.front() < pv) {
                int p = S.front();
                const Eigen::VectorXd& wit =
                    absent ? ctxWitness : node->interior_witness;
                for (size_t i = 1; i < S.size(); ++i) emitNonPartition(p, S[i], G, wit);
                S.erase(S.begin());
            }
            if (absent || S.size() < 2) return;
            if (S.front() != pv) {
                std::println("REPLAY_MISMATCH: scope front {} vs tree pivot {}", S.front(), pv);
                st.genFailures++;
                return;
            }
            // Pivot pv == S.front(): replay its PO-tree.
            std::vector<int> Sfull(S.begin() + 1, S.end());   // S \ {pv}
            replayPO(node, pv, Sfull, Sfull, G);
            return;
        }
    }

    Eigen::VectorXd ctxWitness;   // witness of the enclosing region for absent subtrees

    void replayPO(const aof::Node* v, int p, std::vector<int> C,
                  const std::vector<int>& Sfull, std::vector<Constraint> G) {
        if (v->is_relevant_leaf) {
            ctxStack.push_back(G);
            for (int c : C) emitNonPartition(p, c, G, v->interior_witness);
            aof::Tuple t = aof::computeTuple(*F, *planes, v);
            std::vector<int> Sl, Sr;
            { std::vector<char> inFl(size_t(n) + 1, 0);
              for (int f : t.Fl) inFl[f] = 1;
              for (int f : Sfull) (inFl[f] ? Sl : Sr).push_back(f); }
            ctxWitness = v->interior_witness;
            replayTask(v->left.get(), Sl, G);
            ctxWitness = v->interior_witness;
            replayTask(v->right.get(), Sr, G);
            return;
        }
        // Internal cut node of pivot p's PO-tree.
        aof::PairInfo pr = aof::unrankPair(size_t(v->splitting_plane_id - 1), size_t(n));
        int j = (pr.i == p) ? pr.j : pr.i;
        ctxStack.push_back(G);
        std::vector<int> C2;
        for (int c : C) {
            if (c < j) emitNonPartition(p, c, G, v->interior_witness);
            else if (c != j) C2.push_back(c);
        }
        emitPartition(p, j, v);
        Eigen::VectorXd hw = pairPlane(p, j);        // A_min - A_max of the cut pair
        std::vector<Constraint> Gl = G, Gr = G;
        Gl.push_back({ Eigen::VectorXd(-hw) });      // left region: hw <= 0
        Gr.push_back({ hw });                        // right region: hw >= 0
        replayPO(v->left.get(),  p, C2, Sfull, Gl);
        replayPO(v->right.get(), p, C2, Sfull, Gr);
    }

    // ---- Owner: verify all certificates arithmetically. ----
    void ownerVerify() {
        auto t0 = Clock::now();
        for (size_t i = 0; i < farkas.size(); ++i) {
            const auto& fc = farkas[i];
            const auto& G = ctxStack[ctxNP[i]];
            Eigen::VectorXd w = pairPlane(fc.p, fc.c);
            if (fc.sign < 0) w = -w;
            Eigen::VectorXd acc = Eigen::VectorXd::Zero(d);
            bool ok = true;
            for (auto& [idx, val] : fc.y) {
                if (idx < 0 || idx >= int(G.size()) || val < 0.0) { ok = false; break; }
                acc += val * G[size_t(idx)].a;
            }
            if (ok && (acc - w).cwiseAbs().maxCoeff() > 1e-6 * std::max(1.0, w.cwiseAbs().maxCoeff()))
                ok = false;
            if (!ok) st.verifyFailures++;
        }
        // Floating-point tolerance for geometric checks.  All certificate data
        // is rational (integer coefficients, rational witnesses), so a
        // production owner verifies these predicates EXACTLY in rational
        // arithmetic; the benchmark uses doubles end-to-end and therefore
        // allows scale-aware slop accumulated by the geometric cascade.
        auto tol = [](const Eigen::VectorXd& g) { return 1e-5 * (1.0 + g.cwiseAbs().maxCoeff()); };
        size_t failSign = 0, failAncestor = 0, failBox = 0;
        for (size_t i = 0; i < parts.size(); ++i) {
            const auto& pc = parts[i];
            const auto& G = ctxStack[ctxP[i]];
            Eigen::VectorXd hw = pairPlane(pc.p, pc.j);
            bool ok = true;
            double th = tol(hw);
            if (!(hw.dot(pc.xNeg) < th && hw.dot(pc.xPos) > -th)) { ok = false; failSign++; }
            if (ok) for (size_t gi = 0; gi < G.size(); ++gi) {
                double tg = tol(G[gi].a);
                if (G[gi].a.dot(pc.xNeg) <= -tg || G[gi].a.dot(pc.xPos) <= -tg) {
                    ok = false; failAncestor++; break;
                }
            }
            if (ok) for (int t = 0; t < d; ++t) {
                if (pc.xNeg[t] <= -1e-7 || pc.xNeg[t] >= 1.0 + 1e-7 ||
                    pc.xPos[t] <= -1e-7 || pc.xPos[t] >= 1.0 + 1e-7) { ok = false; failBox++; break; }
            }
            if (!ok) st.verifyFailures++;
        }
        if (failSign + failAncestor + failBox > 0)
            std::println("PARTITION_FAIL sign={} ancestor={} box={}", failSign, failAncestor, failBox);
        st.verifySec = secs(t0, Clock::now());
    }
};

std::vector<Constraint> boxConstraints(int d) {
    std::vector<Constraint> G;
    for (int t = 0; t < d; ++t) {
        Eigen::VectorXd e = Eigen::VectorXd::Zero(d); e[t] = 1.0;
        G.push_back({ e });                   // x_t >= 0  (homogeneous lower facets)
    }
    return G;
}

} // namespace cb

int main(int argc, char* argv[]) {
    if (argc < 3) { std::println("Usage: {} <n> <d>", argv[0]); return 1; }
    int n = std::stoi(argv[1]);
    int d = std::stoi(argv[2]);

    std::string funcFile = std::format("{}_functions_{}d.bin", n, d);
    std::string pairFile = std::format("{}_pairwise_{}d.bin", n, d);
    if (!std::filesystem::exists(funcFile)) { std::println("missing {}", funcFile); return 1; }

    CompactDataset funcs = CompactIO::load(funcFile);
    CompactDataset pairsDs = CompactIO::load(pairFile);
    aof::FunctionTable F; F.init(funcs);
    std::vector<Eigen::VectorXd> planes;
    for (size_t i = 0; i < pairsDs.count; ++i) {
        Eigen::VectorXd h(d);
        for (int j = 0; j < d; ++j) h[j] = double(pairsDs.at(i, j));
        planes.push_back(h);
    }

    auto t0 = Clock::now();
    auto builder = aof::buildAof(F, planes, n, d);
    auto t1 = Clock::now();
    double localConstruct = secs(t0, t1);

    cb::Replayer rp(F, planes);
    rp.ctxWitness = Eigen::VectorXd::Constant(d, 0.5);
    std::vector<int> S(n); for (int i = 0; i < n; ++i) S[i] = i + 1;

    auto g0 = Clock::now();
    rp.replayTask(builder->root.get(), S, cb::boxConstraints(d));
    auto g1 = Clock::now();
    double replaySec = secs(g0, g1);

    rp.ownerVerify();
    size_t honestFailures = rp.st.verifyFailures;
    double honestVerifySec = rp.st.verifySec;

    // Owner also computes tuples + commitments (work paid locally too).
    aof::AdsStats ads;
    auto c0 = Clock::now();
    aof::commitNode(F, planes, builder->root.get(), ads);
    auto c1 = Clock::now();

    // Falsification self-tests (each on a fresh failure counter).
    int tampered = 0, caught = 0;
    if (!rp.farkas.empty()) {
        auto& fc = rp.farkas[rp.farkas.size() / 2];
        if (!fc.y.empty()) {
            tampered++;
            double save = fc.y[0].second; fc.y[0].second = save + 1.0;
            rp.st.verifyFailures = 0;
            rp.ownerVerify();
            if (rp.st.verifyFailures > honestFailures) caught++;
            fc.y[0].second = save;
        }
    }
    if (!rp.parts.empty()) {
        // Tamper a certificate whose witnesses are non-degenerate (clearly off
        // the plane relative to the verification tolerance).
        size_t pick = rp.parts.size() / 2;
        for (size_t i = 0; i < rp.parts.size(); ++i) {
            const auto& pc = rp.parts[i];
            Eigen::VectorXd hw = rp.pairPlane(pc.p, pc.j);
            double th = 1e-5 * (1.0 + hw.cwiseAbs().maxCoeff());
            if (hw.dot(pc.xNeg) < -100 * th && hw.dot(pc.xPos) > 100 * th) { pick = i; break; }
        }
        auto& pc = rp.parts[pick];
        tampered++;
        auto save = pc.xNeg; pc.xNeg = pc.xPos;           // wrong-side witness
        rp.st.verifyFailures = 0;
        rp.ownerVerify();
        if (rp.st.verifyFailures > honestFailures) caught++;
        pc.xNeg = save;
    }
    rp.st.verifyFailures = honestFailures;
    rp.st.verifySec = honestVerifySec;

    std::println("n={} d={}", n, d);
    std::println("LOCAL_CONSTRUCT_SEC={:.6f}", localConstruct);
    std::println("CERT_PARTITION={} CERT_NONPARTITION={} DEVIATIONS_DETECTED={}",
                 rp.st.nPartition, rp.st.nNonPartition, rp.st.genFailures);
    std::println("CERT_BYTES={} NNZ_AVG={:.2f} NNZ_MAX={}",
                 rp.st.bytes,
                 rp.st.nNonPartition ? double(rp.st.nnzTotal) / double(rp.st.nNonPartition) : 0.0,
                 rp.st.maxNnz);
    std::println("CLOUD_GEN_SEC={:.6f} (replay {:.6f})", rp.st.genSec, replaySec);
    std::println("OWNER_CERT_VERIFY_SEC={:.6f} VERIFY_FAILURES={}",
                 rp.st.verifySec, rp.st.verifyFailures);
    std::println("OWNER_COMMIT_SEC={:.6f}", secs(c0, c1));
    std::println("TAMPER_CAUGHT={}/{}", caught, tampered);

    std::ofstream csv("cert_bench_results.csv", std::ios::app);
    csv << std::format("{},{},{:.6f},{},{},{},{:.2f},{},{:.6f},{:.6f},{:.6f},{},{}\n",
        n, d, localConstruct, rp.st.nPartition, rp.st.nNonPartition, rp.st.bytes,
        rp.st.nNonPartition ? double(rp.st.nnzTotal) / double(rp.st.nNonPartition) : 0.0,
        rp.st.maxNnz, rp.st.genSec, rp.st.verifySec, secs(c0, c1),
        rp.st.verifyFailures, caught);
    // Deviations are DATA (detected constructor imperfections), not harness
    // failures; gate only on verification soundness and tamper detection.
    return (rp.st.verifyFailures == 0 && caught == tampered) ? 0 : 2;
}
